-- Windows login from a domain account
CREATE LOGIN [DOMAIN\jane.doe] FROM WINDOWS;

-- Windows group login for the IT department
CREATE LOGIN [DOMAIN\IT_Admins] FROM WINDOWS;

-- SQL Server authentication login
CREATE LOGIN report_writer WITH PASSWORD = 'R3p0rt!2026', CHECK_POLICY = ON;

-- Login from a certificate
CREATE LOGIN cert_login FROM CERTIFICATE ReportingCert;

USE [AppDB];

-- Create a user mapped to an existing login
CREATE USER [jane.doe] FOR LOGIN [DOMAIN\jane.doe] WITH DEFAULT_SCHEMA = [dbo];

-- Create a user without a login (for contained databases)
CREATE USER [external_consultant] WITH PASSWORD = 'C0nsult!2026';

-- Create a custom database role
CREATE ROLE [ReportReaders];

-- Add user to the role
ALTER ROLE [ReportReaders] ADD MEMBER [jane.doe];
